-- ==== 20261012000043_check_numbers_at_sign_up.sql
-- The check numbers at sign-up, as the owner asked: a trader who ticks a trade that needs a check gives its number and
-- the expiry on their card or badge in the form (Gas Safe registration number; DVSA ADI badge number). They still go
-- live without that trade; the admin looks the number up on the Gas Safe or DVSA site and presses one button, which
-- records the check and adds the trade.
--
-- * providers.signup_refs: {"gas_safe" | "dvsa_adi": {"ref", "expires", "slug"}}, the numbers waiting for the admin.
-- * public.trader_publish_listing gains p_refs (000042's otherwise): a ticked check trade without a number and an
--   expiry from today to six years ahead is 'invalid'.
-- * public.admin_confirm_signup_check(provider, kind): records the check (the number and expiry given), adds the
--   trade and clears it from what's waiting. admin_get_provider adds signup_refs.
-- Re-runnable.

alter table public.providers add column if not exists signup_refs jsonb;

drop function if exists public.trader_publish_listing(uuid, text, text, text[], text[], text, text, text, text, text, jsonb);
create or replace function public.trader_publish_listing(
  p_user_id uuid, p_business_name text, p_contact_name text, p_category_slugs text[], p_areas text[],
  p_phone_e164 text, p_whatsapp_e164 text, p_email text, p_plan text, p_ip_hash text, p_evidence jsonb,
  p_refs jsonb default '{}'
) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v_verdict text;
  v_id uuid;
  v_slug text;
  v_cats public.categories[];
  v_listed uuid[];
  v_waiting text;
  v_trades text;
  v_areas text[] := coalesce(array(select distinct upper(btrim(a)) from unnest(coalesce(p_areas, '{}')) a
                                   where nullif(btrim(a), '') is not null order by 1), '{}');
  v_whatsapp text := nullif(btrim(coalesce(p_whatsapp_e164, '')), '');
  v_refs jsonb := '{}';
  v_ref jsonb;
  v_c public.categories;
begin
  if p_user_id is null or not private.valid_consent_evidence(p_evidence) then
    return jsonb_build_object('result', 'invalid');
  end if;
  select coalesce(array_agg(c order by c.name), '{}') into v_cats
  from public.categories c where c.active and c.slug = any (coalesce(p_category_slugs, '{}'));
  if cardinality(v_cats) < 1 or cardinality(v_cats) > 3
     or cardinality(v_areas) < 1 or cardinality(v_areas) > 12
     or exists (select 1 from unnest(v_areas) a where a !~ '^[A-Z]{1,2}[0-9]{1,2}$')
     or (v_whatsapp is not null and v_whatsapp !~ '^\+44[0-9]{9,10}$') then
    return jsonb_build_object('result', 'invalid');
  end if;
  -- Each ticked trade that needs a check (Gas Safe, DVSA) comes with its number and the expiry on the card or badge.
  foreach v_c in array v_cats loop
    if v_c.requirement in ('gas_safe', 'dvsa_adi') then
      v_ref := coalesce(p_refs, '{}') -> (v_c.requirement::text);
      if v_ref is null or coalesce(v_ref ->> 'ref', '') !~ '^[A-Za-z0-9]{4,12}$'
         or coalesce(v_ref ->> 'expires', '') !~ '^\d{4}-\d{2}-\d{2}$'
         or (v_ref ->> 'expires')::date < current_date or (v_ref ->> 'expires')::date > current_date + interval '6 years' then
        return jsonb_build_object('result', 'invalid');
      end if;
      v_refs := v_refs || jsonb_build_object(v_c.requirement::text, jsonb_build_object(
        'ref', upper(v_ref ->> 'ref'), 'expires', v_ref ->> 'expires', 'slug', v_c.slug));
    end if;
  end loop;
  -- The same account checks as the admin's approval (000038): a live account with a normal sign-in, not blocked,
  -- not the admin.
  if not exists (select 1 from auth.users where id = p_user_id and deleted_at is null)
     or not exists (select 1 from public.profiles where user_id = p_user_id and deleted_at is null)
     or coalesce(private.sign_in_kind(p_user_id), '') not in ('google', 'email', 'phone')
     or exists (select 1 from public.profiles where user_id = p_user_id and (blocked_at is not null or role = 'admin')) then
    return jsonb_build_object('result', 'not_allowed');
  end if;
  -- One listing per account (a removed one doesn't count: they can list again), and per number (000034).
  if exists (select 1 from public.providers where user_id = p_user_id and status <> 'removed') then
    return jsonb_build_object('result', 'already');
  end if;
  if exists (select 1 from public.providers where status <> 'removed'
             and (phone_e164 in (p_phone_e164, v_whatsapp) or whatsapp_e164 in (p_phone_e164, v_whatsapp))) then
    return jsonb_build_object('result', 'duplicate');
  end if;

  v_trades := left(array_to_string(array(select (c).name from unnest(v_cats) c), ', '), 60);
  -- The request is kept as the record (and carries the limits: three a day per connection, two a week per number).
  v_verdict := public.submit_listing_request(p_business_name, p_contact_name, v_trades, v_areas[1], p_phone_e164,
                                             p_email, null, p_ip_hash, p_user_id, p_plan);
  if v_verdict <> 'ok' then
    return jsonb_build_object('result', v_verdict);
  end if;
  update public.listing_requests set status = 'done', handled_at = now()
  where user_id = p_user_id and status = 'new';

  v_waiting := nullif(left(array_to_string(array(select (c).name from unnest(v_cats) c
                                                 where (c).requirement in ('gas_safe', 'dvsa_adi')), ', '), 60), '');
  insert into public.providers (slug, business_name, contact_name, phone_e164, whatsapp_e164, areas, user_id, status,
                                consent_at, consent_evidence, consent_token_used_at, signup_trade, reviewed_at, signup_refs)
  values (private.unique_slug(btrim(p_business_name)), btrim(p_business_name), nullif(btrim(coalesce(p_contact_name, '')), ''),
          p_phone_e164, v_whatsapp, v_areas, p_user_id, 'live', now(),
          p_evidence || jsonb_build_object('via', 'sign_up', 'accepted_at', now()), now(), v_waiting, null,
          nullif(v_refs, '{}'::jsonb))
  returning id, slug into v_id, v_slug;
  -- Trades that need a check first (Gas Safe, DVSA) wait for the admin; the rest are listed now.
  insert into public.provider_categories (provider_id, category_id)
  select v_id, (c).id from unnest(v_cats) c where (c).requirement not in ('gas_safe', 'dvsa_adi');
  update public.profiles set role = 'provider' where user_id = p_user_id and role = 'resident';

  insert into public.audit_log (actor_id, action, target_type, target_id)
  values (p_user_id, 'trader_publish_listing', 'provider', v_id::text);
  return jsonb_build_object('result', 'ok', 'id', v_id, 'slug', v_slug);
end;
$$;
revoke execute on function public.trader_publish_listing(uuid, text, text, text[], text[], text, text, text, text, text, jsonb, jsonb)
  from public, anon, authenticated;
grant execute on function public.trader_publish_listing(uuid, text, text, text[], text[], text, text, text, text, text, jsonb, jsonb)
  to service_role;

create or replace function public.admin_confirm_signup_check(p_provider uuid, p_kind public.check_kind) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_ref jsonb;
  v_left jsonb;
begin
  if not public.is_admin() then
    raise exception 'not admin' using errcode = '42501';
  end if;
  select signup_refs -> (p_kind::text), signup_refs - (p_kind::text) into v_ref, v_left
  from public.providers where id = p_provider for update;
  if v_ref is null then
    raise exception 'nothing_to_confirm';
  end if;
  insert into public.provider_checks (provider_id, kind, reference, expires_on, checked_by)
  values (p_provider, p_kind, v_ref ->> 'ref', (v_ref ->> 'expires')::date, auth.uid());
  -- Now the check is in date, the trade can be added (enforce_category_requirement).
  insert into public.provider_categories (provider_id, category_id)
  select p_provider, c.id from public.categories c where c.slug = v_ref ->> 'slug'
  on conflict do nothing;
  update public.providers
  set signup_refs = nullif(v_left, '{}'::jsonb),
      signup_trade = nullif(left(array_to_string(array(
        select c.name from public.categories c
        where c.slug in (select e.value ->> 'slug' from jsonb_each(coalesce(v_left, '{}'::jsonb)) e)
        order by c.name), ', '), 60), '')
  where id = p_provider;
  insert into public.audit_log (actor_id, action, target_type, target_id, reason)
  values (auth.uid(), 'confirm_signup_check', 'provider', p_provider::text, p_kind::text);
end;
$$;
revoke execute on function public.admin_confirm_signup_check(uuid, public.check_kind) from public, anon;
grant execute on function public.admin_confirm_signup_check(uuid, public.check_kind) to authenticated;

-- 000041 body, plus the check numbers waiting for the admin.
create or replace function public.admin_get_provider(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = ''
as $$
declare
  v jsonb;
begin
  if not public.is_admin() then
    raise exception 'not admin' using errcode = '42501';
  end if;
  select jsonb_build_object(
    'id', p.id, 'slug', p.slug, 'business_name', p.business_name, 'contact_name', p.contact_name,
    'phone_e164', p.phone_e164, 'whatsapp_e164', p.whatsapp_e164, 'areas', p.areas, 'bio', p.bio,
    'status', p.status, 'consent_at', p.consent_at, 'consent_token_expires_at', p.consent_token_expires_at,
    'category_ids', coalesce((select jsonb_agg(pc.category_id) from public.provider_categories pc where pc.provider_id = p.id), '[]'::jsonb),
    'checks', coalesce((select jsonb_agg(jsonb_build_object('id', ck.id, 'kind', ck.kind, 'reference', ck.reference,
                'expires_on', ck.expires_on, 'checked_at', ck.checked_at) order by ck.checked_at desc)
              from public.provider_checks ck where ck.provider_id = p.id), '[]'::jsonb),
    'linked', p.user_id is not null,
    'owner_email', (select u.email from auth.users u where u.id = p.user_id),
    'trader_link_expires_at', (
      select t.expires_at from public.trader_link_tokens t
      where t.provider_id = p.id and t.used_at is null and t.revoked_at is null and t.expires_at > now()
      order by t.created_at desc limit 1
    ),
    'availability', jsonb_build_object('status', p.availability, 'until', p.available_until,
      'set_at', p.availability_set_at,
      'showing', private.availability_now(p.availability, p.available_until, p.availability_set_at)),
    'reviewed_at', p.reviewed_at, 'signup_trade', p.signup_trade, 'created_at', p.created_at,
    -- Whether a consent link was made before: a new one cancels it, so the admin is asked first.
    'signup_refs', coalesce(p.signup_refs, '{}'::jsonb),
    'consent_link_made', exists (select 1 from public.audit_log a where a.target_type = 'provider'
                                 and a.target_id = p.id::text and a.action = 'new_consent_token')
  ) into v
  from public.providers p where p.id = p_id;
  return v;
end;
$$;

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000043', 'check_numbers_at_sign_up') on conflict do nothing;

-- ==================================================================== verification
-- Fails (and so rolls back everything above) if any piece is missing.
do $verify$
begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'providers'
                 and column_name = 'signup_refs') then
    raise exception 'Check numbers check failed: providers.signup_refs is missing';
  end if;
  if to_regprocedure('public.trader_publish_listing(uuid, text, text, text[], text[], text, text, text, text, text, jsonb, jsonb)') is null
     or (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
         where n.nspname = 'public' and p.proname = 'trader_publish_listing') <> 1 then
    raise exception 'Check numbers check failed: trader_publish_listing (with the check numbers) is missing, or an old one is still there';
  end if;
  if to_regprocedure('public.admin_confirm_signup_check(uuid, public.check_kind)') is null then
    raise exception 'Check numbers check failed: admin_confirm_signup_check is missing';
  end if;
  if has_function_privilege('authenticated', 'public.trader_publish_listing(uuid, text, text, text[], text[], text, text, text, text, text, jsonb, jsonb)', 'execute') then
    raise exception 'Check numbers check failed: a signed-in account could call trader_publish_listing';
  end if;
end
$verify$;

commit;

select 'Check numbers applied' as result,
       (select count(*) from supabase_migrations.schema_migrations where version in ('20261012000043')) as migrations_recorded;
